const enabled={enabled:true,repair:true,repairBelowDurabilityRatio:1,maximumRepairPetrolPerPlan:100000,move:true,cargoFill:true,cargoClaim:true};
function facts(){return {config:{tables:{}},now:100,parameters:{},stockReliable:true,stock:new Map([['汽油',2000],['木材',10],['EXP',10],['GOLD',100]]),fleetReliable:true,fleets:[{buildingId:'f1',state:1,durability:1500,maxDura:2000,cityId:1,targetCityId:0,treasureLootUid:0,repairing:null,autoFight:{isOn:false,todayTimes:0}}],repairParams:new Map([['f1',{unitRepairCost:2.2,unitRepairTime:0.15}]]),citiesReliable:true,cities:[{id:2,state:1,guildIdx:3}],guildIdx:3,cargoReliable:true,ships:[{index:1,status:0,arriveTime:0,orderItem:[{filled:false,asset:{type:0,id:'木材',num:6},reward:{asset:[{type:1,id:'EXP',num:2},{type:1,id:'GOLD',num:3}]}}],reward:[{type:0,id:'藏品大师徽章',num:3}]}],protocolReady:{RepairFleetRequest:true,MoveFleetsToCityRequest:true,FillCargoShipRequest:true,DrawShipRewardRequest:true}}}
function view(f=facts(),parameters={}){return fleetView(f,{moduleConfig:enabled,parameters})}
function op(f=facts(),kind='fleetRepair',parameters={}){return view(f,parameters).candidates.find(row=>row.actionType===kind)}
test('fleet repair budgets server double cost with upward rounding',()=>{const f=facts(),action=op(f);assert.equal(action.decision,'READY');assert.equal(action.costs[0].num,1100);assert.equal(action.action.request,'RepairFleetRequest');assert.equal(action.action.response,null);assert.equal(planFleet(f,{moduleConfig:enabled,selections:[action.actionId]}).actions.length,1)});
test('repair requires server parameters and reliable idle fleet',()=>{for(const mutate of [f=>f.repairParams.clear(),f=>f.repairParams.get('f1').unitRepairCost=0,f=>f.fleetReliable=false,f=>f.stockReliable=false,f=>f.fleets[0].state=4,f=>f.fleets[0].durability=null,f=>f.stock.set('汽油',1000)]){const f=facts();mutate(f);assert.equal(op(f).decision,'BLOCKED')}});
test('shared fleet budget and one-action-per-fleet prevent double spend',()=>{const f=facts();f.fleets[0].durability=1900;const a=op(f),b=op(f,'fleetMove',{cityId:2});const plan=planFleet(f,{moduleConfig:enabled,parameters:{cityId:2},selections:[a.actionId,b.actionId],ledger:new ResourceLedger(f.stock)});assert.equal(plan.actions.length,1);assert.ok(plan.notes.some(note=>note.includes('预占')))});
test('fleet move is target-bound movement only and unknown cost blocks',()=>{const f=facts();f.fleets[0].durability=1900;const a=op(f,'fleetMove',{cityId:2});assert.equal(a.decision,'READY');assert.deepEqual(a.action.body,{buildingId:['f1'],cityId:2});assert.equal(a.expectedState.scope,'MOVEMENT_ONLY');f.cities[0].guildIdx=9;assert.equal(op(f,'fleetMove',{cityId:2}).reason,'MOVE_COST_UNKNOWN')});
test('premium acceleration, automatic fighting and fleet formation stay blocked',()=>{const v=view();assert.equal(v.blocked.find(row=>row.actionType==='speedUpFleet').code,'PREMIUM_BLOCKED');for(const kind of ['speedUpRepair','speedUpCargo'])assert.equal(v.blocked.find(row=>row.actionType===kind).code,'EXACT_ITEM_SELECTION_REQUIRED');assert.equal(v.candidates.some(row=>row.actionType==='autoFight'),false);assert.equal(fleetModule.defaultConfig.enabled,false)});
