test('cargo verify requires exact slot, original reward, inventory and consumed arrival',()=>{
 const before=facts(),after=facts(),action=op(before,'cargoFill');
 after.ships[0].orderItem[0].filled=true;after.ships[0].status=1;after.ships[0].arriveTime=200;
 const fillReward={reward:structuredClone(before.ships[0].orderItem[0].reward)};
 assert.equal(verifyFleet(action,before,after,{}).confirmed,false);
 assert.equal(verifyFleet(action,before,after,fillReward).confirmed,false);
 after.stock.set('木材',4);after.stock.set('EXP',12);after.stock.set('GOLD',103);
 assert.equal(verifyFleet(action,before,after,fillReward).confirmed,true);
 after.ships[0].orderItem[0].asset.id='wrong';assert.equal(verifyFleet(action,before,after,fillReward).confirmed,false);
 const arrived=facts();arrived.ships[0].status=2;arrived.ships[0].arriveTime=100;arrived.ships[0].orderItem[0].filled=true;
 const claimed=facts(),claim=op(arrived,'cargoClaim');
 assert.equal(verifyFleet(claim,arrived,claimed,{ship:{index:1},reward:{asset:[{id:'木材',num:1}]}}).confirmed,false);
 const claimResponse={ship:structuredClone(claimed.ships[0]),reward:{asset:structuredClone(arrived.ships[0].reward)}};
 assert.equal(verifyFleet(claim,arrived,claimed,claimResponse).confirmed,false);
 claimed.stock.set('藏品大师徽章',3);
 assert.equal(verifyFleet(claim,arrived,claimed,claimResponse).confirmed,true);
 assert.equal(verifyFleet(claim,arrived,claimed,{}).confirmed,false);
});
test('fleet survey repair parameter requests are sequential, read-only and source-bound',async()=>{const responses={MyFleetsRequest:{fleets:[facts().fleets[0],{...facts().fleets[0],buildingId:'f2'}]},AllItemRequest:{items:[{itemId:'汽油',num:2000}]},AllResourceRequest:{list:[]},CargoShipsRequest:{ship:[]},WorldInfoRequest:{cities:[]},GuildInfoRequest:{guild:{guildId:3003}},FleetRepairParamRequest:{unitRepairCost:2.2,unitRepairTime:0.15}};const protocol=Object.fromEntries(Object.keys(responses).flatMap(name=>[[name,{}],[name.replace('Request','Response'),{}]]));let active=0,max=0,repairs=[];const f=await surveyFleet({connected:true,request:async(name,body)=>{if(name==='FleetRepairParamRequest'){active++;max=Math.max(max,active);repairs.push(body.buildingId);await new Promise(resolve=>setTimeout(resolve,2));active--}return responses[name]}},protocol,{moduleConfig:{repair:true}});assert.equal(max,1);assert.deepEqual(repairs,['f1','f2']);assert.equal(f.repairParams.size,2);assert.equal(f.stockReliable,true)});

