test('fleet formation rejects unknown source, nonidle ship, unavailable hero and other fleet occupancy',()=>{for(const mutate of [f=>f.formationFacts.buildingsReliable=false,f=>f.formationFacts.heroesReliable=false,f=>f.fleets[0].state=2,f=>f.fleets[0].autoFight.isOn=true,f=>f.formationFacts.ownedHeroIds=['hero-a'],f=>f.formationFacts.buildings[1].formation.heroPositions[0].heroId='hero-b',f=>f.formationFacts.catalog.maxHeroes=null,f=>f.formationFacts.buildings[0].formation.petUid='9007199254740993']){const f=formationFacts();mutate(f);assert.equal(formationView(f).decision,'BLOCKED')}});
