test('fleet repair item acceleration blocks insufficient remaining items, changed source and late dispatch without transport',async()=>{
 for(const mutate of [f=>f.state.now=1940000,f=>f.client.factContext.generation++,f=>f.state.raw.autoFight.isOn=true,f=>f.state.raw.repairing.startTs=2100,f=>f.state.stock=1]){const f=await repairItemFixture(),op=f.operation();mutate(f);const r=await executeBusinessOperation(f.client,f.protocol,op,{adapter:fleetModule,moduleConfig:f.moduleConfig,player:f.player,allowMutate:true,window:0});assert.equal(r.dispatched,false,JSON.stringify(r));assert.equal(f.state.writes.length,0);}
 const f=await repairItemFixture(),op=f.operation();f.state.onSend=()=>{f.state.now=1940000;};const r=await executeBusinessOperation(f.client,f.protocol,op,{adapter:fleetModule,moduleConfig:f.moduleConfig,player:f.player,allowMutate:true,window:0});assert.notEqual(r.status,'SUCCESS');assert.equal(f.state.writes.length,0);
});


test('fleet repair item acceleration confirms bounded completion and blocks ambiguous phase or overdue natural finish',async()=>{
 const f=await repairItemFixture({endTs:1120}),op=f.operation();assert.equal(op.expectedState.completed,true);assert.equal(op.expectedState.repairEndTs,null);const r=await executeBusinessOperation(f.client,f.protocol,op,{adapter:fleetModule,moduleConfig:f.moduleConfig,player:f.player,allowMutate:true,window:0});assert.equal(r.status,'SUCCESS',JSON.stringify(r));assert.equal(f.state.raw.state,1);assert.equal(f.state.raw.durability,200);assert.equal(f.state.raw.repairing,null);assert.equal(f.state.stock,0);
 const g=await repairItemFixture({endTs:1120});g.client.gameClock.read=()=>({status:'TRUSTED',reliable:true,accountId:'fixture',generation:1,earliestMs:999999,nowMs:1000000,latestMs:1000001});assert.equal(g.operation(),undefined);
 const h=await repairItemFixture({endTs:1120}),before=h.operation();h.state.now=1120000;const stopped=await executeBusinessOperation(h.client,h.protocol,before,{adapter:fleetModule,moduleConfig:h.moduleConfig,player:h.player,allowMutate:true,window:0});assert.equal(stopped.dispatched,false);assert.equal(h.state.writes.length,0);
});
